627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0648\u0633\u0627\u062f\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0633\u0641\u0644\u064a\u0629\u060c \u0645\u0639 \u062a\u0648\u062c\u064a\u0647 \u0631\u0627\u062d\u062a\u064a \u0627\u0644\u064a\u062f\u064a\u0646 \u0644\u0644\u0623\u0639\u0644\u0649.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0634\u063a\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u062d\u0631\u0631 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0648\u0645\u062f\u0647\u0645\u0627 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1348","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1348-ZqNOWQ6.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1348-ZqNOWQ6.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"7fd2f005-bc94-5015-8d50-6b9f828579b8","source_id":"0593","name_en":"lever reverse hyperextension","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u0641\u0631\u0637 \u0627\u0644\u062a\u0645\u062f\u062f \u0627\u0644\u0639\u0643\u0633\u064a","match_names":["lever reverse hyperextension"],"muscle":"glutes","equipment":"machine","aliases":["lever reverse hyperextension"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the leverage machine to fit your body and secure your feet in the foot pads.\nLie face down on the machine with your upper body hanging off the edge and your hips resting on the pad.\nCross your arms over your chest or place them behind your head.\nEngage your glutes and hamstrings to lift your legs upward until they are parallel to the ground.\nPause for a moment at the top, then slowly lower your legs back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0622\u0644\u0629 \u0627\u0644\u0631\u0641\u0639 \u0644\u062a\u0646\u0627\u0633\u0628 \u062c\u0633\u0645\u0643 \u0648\u062b\u0628\u062a \u0642\u062f\u0645\u064a\u0643 \u0641\u064a \u0648\u0633\u0627\u062f\u0627\u062a \u0627\u0644\u0642\u062f\u0645.\n\u0627\u0633\u062a\u0644\u0642\u064a \u0639\u0644\u0649 \u0648\u062c\u0647\u0643 \u0644\u0623\u0633\u0641\u0644 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u062a\u0639\u0644\u064a\u0642 \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u062c\u0633\u0645\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0641\u0629 \u0648\u0627\u0633\u062a\u0631\u064a\u062d \u0627\u0644\u0648\u0631\u0643\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629.\n\u0627\u0639\u0628\u0631 \u0630\u0631\u0627\u0639\u064a\u0643 \u0639\u0644\u0649 \u0635\u062f\u0631\u0643 \u0623\u0648 \u0636\u0639\u0647\u0645\u0627 \u062e\u0644\u0641 \u0631\u0623\u0633\u0643.\n\u0642\u0645 \u0628\u0625\u0634\u0631\u0627\u0643 \u0627\u0644\u0623\u0644\u0648\u064a\u0629 \u0648\u0623\u0648\u062a\u0627\u0631 \u0627\u0644\u0631\u0643\u0628\u0629 \u0644\u0631\u0641\u0639 \u0633\u0627\u0642\u064a\u0643 \u0644\u0644\u0623\u0639\u0644\u0649 \u062d\u062a\u0649 \u062a\u0635\u0628\u062d \u0645\u0648\u0627\u0632\u064a\u0629 \u0644\u0644\u0623\u0631\u0636.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0639\u0644\u0649\u060c \u062b\u0645 \u0623\u0646\u0632\u0644 \u0633\u0627\u0642\u064a\u0643 \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0593","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"glutes","secondary_muscles":["hamstrings","lower back"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0593-Krmb3cB.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0593-Krmb3cB.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"b1947667-023e-5759-8eaf-bade21428db6","source_id":"1349","name_en":"lever reverse t-bar row","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u0639\u0643\u0633 \u0635\u0641 T-bar","match_names":["lever reverse t-bar row"],"muscle":"back","equipment":"machine","aliases":["lever reverse t-bar row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height and footplate position on the leverage machine.\nSit on the machine with your chest against the pad and your feet flat on the footplate.\nGrasp the handles with an overhand grip, slightly wider than shoulder-width apart.\nKeep your back straight and engage your core.\nPull the handles towards your chest, squeezing your shoulder blades together.\nPause for a moment at the top of the movement, then slowly release and extend your arms back to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0645\u0648\u0636\u0639 \u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0645\u0627\u0644\u064a\u0629.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0635\u062f\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u0629 \u0639\u0644\u0649 \u0648\u0633\u0627\u062f\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u0639\u0644\u0648\u064a\u0629\u060c \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0645\u062a\u0628\u0627\u0639\u062f\u0629 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u0627\u0634\u063a\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0646\u062d\u0648 \u0635\u062f\u0631\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u062c\u0632\u0621 \u0627\u0644\u0639\u0644\u0648\u064a \u0645\u0646 \u0627\u0644\u062d\u0631\u0643\u0629\u060c \u062b\u0645 \u062d\u0631\u0631 \u0630\u0631\u0627\u0639\u064a\u0643 \u0628\u0628\u0637\u0621 \u0648\u0645\u062f\u0647\u0645\u0627 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1349","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1349-BgljGjd.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1349-BgljGjd.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"01c06d02-29a2-535d-80e1-be1b53821ad9","source_id":"2315","name_en":"lever rotary calf","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u0627\u0644\u0639\u062c\u0644 \u0627\u0644\u062f\u0648\u0627\u0631\u0629","match_names":["lever rotary calf"],"muscle":"calves","equipment":"machine","aliases":["lever rotary calf"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height so that your knees are slightly bent and your feet are flat on the footplate.\nPlace your toes on the footplate, with your heels hanging off the edge.\nGrasp the handles or the sides of the machine for stability.\nPush through the balls of your feet, raising your heels as high as possible.\nPause for a moment at the top, then slowly lower your heels back down to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u0628\u062d\u064a\u062b \u062a\u0643\u0648\u0646 \u0631\u0643\u0628\u062a\u064a\u0643 \u0645\u062b\u0646\u064a\u062a\u064a\u0646 \u0642\u0644\u064a\u0644\u064b\u0627 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u062a\u0648\u064a\u062a\u064a\u0646 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0642\u062f\u0645.\n\u0636\u0639 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u060c \u0645\u0639 \u062a\u0639\u0644\u064a\u0642 \u0643\u0639\u0628\u064a\u0643 \u0639\u0644\u0649 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u0623\u0645\u0633\u0643 \u0628\u0645\u0642\u0627\u0628\u0636 \u0623\u0648 \u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0645\u0627\u0643\u064a\u0646\u0629 \u0644\u062a\u062d\u0642\u064a\u0642 \u0627\u0644\u062b\u0628\u0627\u062a.\n\u0627\u062f\u0641\u0639\u064a \u0645\u0646 \u062e\u0644\u0627\u0644 \u0623\u0645\u0634\u0627\u0637 \u0642\u062f\u0645\u064a\u0643\u060c \u0648\u0627\u0631\u0641\u0639\u064a \u0643\u0639\u0628\u064a\u0643 \