\u0627 \u0627\u0644\u064a\u062f\u064a\u0646 \u0628\u0639\u0636\u0647\u0645\u0627 \u0627\u0644\u0628\u0639\u0636\u060c \u0648\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u062b\u0646\u064a \u0630\u0631\u0627\u0639\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b.\n\u0642\u0645 \u0628\u0627\u0644\u0632\u0641\u064a\u0631 \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627 \u0623\u062b\u0646\u0627\u0621 \u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0644\u0644\u062e\u0644\u0641 \u0648\u0644\u0644\u062e\u0627\u0631\u062c \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u062c\u0633\u0645\u0643.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f \u0630\u0631\u0648\u0629 \u0627\u0644\u0627\u0646\u0643\u0645\u0627\u0634\u060c \u062b\u0645 \u062e\u0630 \u0634\u0647\u064a\u0642\u064b\u0627 \u062b\u0645 \u0639\u062f \u0628\u0628\u0637\u0621 \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"0601","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"delts","secondary_muscles":["trapezius","rhomboids"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/0601-xiHiJcA.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/0601-xiHiJcA.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"e06e6dbd-c0d5-5ee5-8c0f-d086487639ba","source_id":"1350","name_en":"lever seated row","name_ar":"\u0631\u0627\u0641\u0639\u0629 \u064a\u062c\u0644\u0633 \u0627\u0644\u0635\u0641","match_names":["lever seated row"],"muscle":"back","equipment":"machine","aliases":["lever seated row"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat height and footrests to a comfortable position.\nSit on the machine with your chest against the pad and your feet on the footrests.\nGrasp the handles with an overhand grip, shoulder-width apart.\nKeep your back straight and your core engaged.\nPull the handles towards your body, squeezing your shoulder blades together.\nPause for a moment at the peak of the movement.\nSlowly release the handles and return to the starting position.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0627\u0631\u062a\u0641\u0627\u0639 \u0627\u0644\u0645\u0642\u0639\u062f \u0648\u0645\u0633\u0627\u0646\u062f \u0627\u0644\u0642\u062f\u0645\u064a\u0646 \u0639\u0644\u0649 \u0648\u0636\u0639 \u0645\u0631\u064a\u062d.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0635\u062f\u0631\u0643 \u0639\u0644\u0649 \u0627\u0644\u0648\u0633\u0627\u062f\u0629 \u0648\u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0645\u0633\u0627\u0646\u062f \u0627\u0644\u0642\u062f\u0645\u064a\u0646.\n\u0623\u0645\u0633\u0643 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0642\u0628\u0636\u0629 \u064a\u062f \u0645\u062a\u0628\u0627\u0639\u062f\u0629 \u0628\u0645\u0642\u062f\u0627\u0631 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u062d\u0627\u0641\u0638 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0627\u0645\u0629 \u0638\u0647\u0631\u0643 \u0648\u062a\u0641\u0627\u0639\u0644 \u0642\u0644\u0628\u0643.\n\u0627\u0633\u062d\u0628 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0646\u062d\u0648 \u062c\u0633\u0645\u0643\u060c \u0648\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0644\u0648\u062d\u064a \u0643\u062a\u0641\u0643 \u0645\u0639\u064b\u0627.\n\u062a\u0648\u0642\u0641 \u0644\u0644\u062d\u0638\u0629 \u0639\u0646\u062f \u0630\u0631\u0648\u0629 \u0627\u0644\u062d\u0631\u0643\u0629.\n\u062d\u0631\u0631 \u0627\u0644\u0645\u0642\u0627\u0628\u0636 \u0628\u0628\u0637\u0621 \u062b\u0645 \u0639\u062f \u0625\u0644\u0649 \u0648\u0636\u0639 \u0627\u0644\u0628\u062f\u0627\u064a\u0629.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1350","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"upper back","secondary_muscles":["biceps","forearms"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/images/1350-7I6LNUG.jpg","gif":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c265e7cd4b78dfa848e7ce5ebd/videos/1350-7I6LNUG.gif","author":"Gym Visual","license":"Gym Visual commercial catalogue","permission":"Application owner confirmed catalogue licensing","attribution":"\u00a9 Gym Visual \u00b7 gymvisual.com"}}},{"id":"456d808a-591b-55d9-8b74-ca79f754c0db","source_id":"1385","name_en":"lever seated squat calf raise on leg press machine","name_ar":"\u0631\u0641\u0639 \u0631\u0628\u0644\u0629 \u0627\u0644\u0633\u0627\u0642 \u0627\u0644\u0642\u0631\u0641\u0635\u0627\u0621 \u0628\u0627\u0644\u0631\u0627\u0641\u0639\u0629 \u0639\u0644\u0649 \u0622\u0644\u0629 \u0636\u063a\u0637 \u0627\u0644\u0633\u0627\u0642","match_names":["lever seated squat calf raise on leg press machine"],"muscle":"calves","equipment":"machine","aliases":["lever seated squat calf raise on leg press machine"],"logging_mode":"weighted_reps","load_convention":"external_total","guidance":{"steps_en":"Adjust the seat of the leg press machine so that your knees are slightly bent when your feet are on the footplate.\nSit on the machine with your back against the backrest and your feet flat on the footplate, shoulder-width apart.\nPlace your toes and the balls of your feet on the footplate, keeping your heels off the edge.\nRelease the safety handles and push the footplate away from you by extending your knees.\nOnce your knees are fully extended, slowly lower your heels by flexing your calves.\nPause for a moment at the bottom, then push the footplate back up by extending your calves.\nRepeat for the desired number of repetitions.","steps_ar":"\u0627\u0636\u0628\u0637 \u0645\u0642\u0639\u062f \u0622\u0644\u0629 \u0636\u063a\u0637 \u0627\u0644\u0633\u0627\u0642 \u0628\u062d\u064a\u062b \u062a\u0646\u062d\u0646\u064a \u0631\u0643\u0628\u062a\u064a\u0643 \u0642\u0644\u064a\u0644\u0627\u064b \u0639\u0646\u062f\u0645\u0627 \u062a\u0643\u0648\u0646 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645.\n\u0627\u062c\u0644\u0633 \u0639\u0644\u0649 \u0627\u0644\u062c\u0647\u0627\u0632 \u0645\u0639 \u0648\u0636\u0639 \u0638\u0647\u0631\u0643 \u0639\u0644\u0649 \u0645\u0633\u0646\u062f \u0627\u0644\u0638\u0647\u0631 \u0648\u0642\u062f\u0645\u064a\u0643 \u0645\u0633\u0637\u062d\u062a\u064a\u0646 \u0639\u0644\u0649 \u0644\u0648\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u060c \u0645\u0639 \u0639\u0631\u0636 \u0627\u0644\u0643\u062a\u0641\u064a\u0646.\n\u0636\u0639 \u0623\u0635\u0627\u0628\u0639 \u0642\u062f\u0645\u064a\u0643 \u0648\u0645\u0634\u0637 \u0642\u062f\u0645\u064a\u0643 \u0639\u0644\u0649 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645\u060c \u0645\u0639 \u0625\u0628\u0642\u0627\u0621 \u0643\u0639\u0628\u064a\u0643 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646 \u0627\u0644\u062d\u0627\u0641\u0629.\n\u062d\u0631\u0631 \u0645\u0642\u0627\u0628\u0636 \u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0627\u062f\u0641\u0639 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0628\u0639\u064a\u062f\u064b\u0627 \u0639\u0646\u0643 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0645\u062f \u0631\u0643\u0628\u062a\u064a\u0643.\n\u0628\u0645\u062c\u0631\u062f \u062a\u0645\u062f\u064a\u062f \u0631\u0643\u0628\u062a\u064a\u0643 \u0628\u0627\u0644\u0643\u0627\u0645\u0644\u060c \u0642\u0645 \u0628\u062e\u0641\u0636 \u0643\u0639\u0628\u064a\u0643 \u0628\u0628\u0637\u0621 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062b\u0646\u064a \u0633\u0627\u0642\u064a\u0643.\n\u062a\u0648\u0642\u0641 \u0645\u0624\u0642\u062a\u064b\u0627 \u0644\u0644\u062d\u0638\u0629 \u0641\u064a \u0627\u0644\u0623\u0633\u0641\u0644\u060c \u062b\u0645 \u0627\u062f\u0641\u0639 \u0635\u0641\u064a\u062d\u0629 \u0627\u0644\u0642\u062f\u0645 \u0644\u0644\u0623\u0639\u0644\u0649 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649 \u0639\u0646 \u0637\u0631\u064a\u0642 \u062a\u0645\u062f\u064a\u062f \u0633\u0627\u0642\u064a\u0643.\n\u0643\u0631\u0631 \u0627\u0644\u0639\u062f\u062f \u0627\u0644\u0645\u0637\u0644\u0648\u0628 \u0645\u0646 \u0627\u0644\u062a\u0643\u0631\u0627\u0631.","text_source":{"repository":"hasaneyldrm/exercises-dataset","revision":"7455efae41b330c265e7cd4b78dfa848e7ce5ebd","exercise_id":"1385","license":"MIT"},"translation":{"provider":"Google Translate public-text preparation","language":"ar","status":"machine_draft","prepared_on":"2026-11-07"},"catalogue_kind":"strength","classification_status":"needs_review","source_target":"calves","secondary_muscles":["quadriceps","hamstrings","glutes"],"catalogue_media":{"poster":"https://raw.githubusercontent.com/hasaneyldrm/exercises-dataset/7455efae41b330c